function bkV2ReconfirmClear(bkId){ const b=SB_BOOKINGS.find(x=>x.id===bkId); if(!b||!b.ops) return; b.ops.reconfirm=null; acctPersistBookings(); if(typeof bkV2Render==='function') bkV2Render(); }
