  if(Array.isArray(o.vanSplits)&&o.vanSplits.length){ const rs=o.vanSplits.map(s=>s.vanReturnId).filter(Boolean); arranged=rs.length>0&&rs.length===o.vanSplits.length; retId=rs[0]||null; }
