          const _rd = (vid && typeof vanJobsDriverInfo==='function')?vanJobsDriverInfo(vid,date):{driver:(v&&v.driver)||'',phone:(v&&v.driverPhone)||'',plate:(v&&v.plate)||'',override:false,plateOverride:false};
