function bkV2VoucherLiveCheck(val){ const el=document.getElementById('bkv2-voucher-dup-warn'); if(el) el.innerHTML=bkV2VoucherDupHtml(val); }
/* §editCarry · fields that are NOT rebuilt from the booking form, so bkV2CommitBooking must copy them
   from the booking being edited onto the fresh object — miss one and every edit silently wipes it.
   A new field that lives on the booking but isn't in the form goes in one of these lists.
   'arr' = copy only when it is an array · 'set' = copy only when truthy.
   Two groups on purpose: between them bkV2CommitBooking clears a moved travel day's boat/van (and
   snapshots it via ckStrandSnap) — that step must see `ops` but not yet the day-of records.
   test/unit/booking-edit-carry.test.mjs pins this list. */
const BK_EDIT_CARRY = {
  early: [['history','arr'], ['weatherResolve','set'], ['rebook','set'], ['invoiceId','set'], ['paymentStatus','set'], ['ops','set']],
  dayOf: [['upgrades','arr'], ['feeItems','arr'], ['reschedule','set'], ['partialCancels','arr'], ['cancellation','set'], ['cancelCategory','set']],
};
function bkV2CarryOver(from, to, group){
  for(const [k, how] of BK_EDIT_CARRY[group]){
    if(how==='arr' ? Array.isArray(from[k]) : from[k]) to[k] = from[k];
  }
}
