  const rows=BKV2_PAX_KEYS.filter(([k])=>(t.pax&&t.pax[k]>0)).map(([k,lab])=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:5px 0;border-bottom:0.5px solid rgba(0,0,0,.05)"><span style="font-size:12.5px">${lab} <span style="color:var(--fd-ink-soft);font-family:'DM Mono',monospace">(${t.pax[k]})</span></span><span style="font-size:11px;color:var(--fd-ink-soft)">remove <input id="bkp-rm-${k}" type="number" min="0" max="${t.pax[k]}" value="0" oninput="bkV2PartialRecalc()" style="width:60px;font-size:13px;padding:4px 8px;border:1px solid var(--fd-line);border-radius:7px;font-family:inherit;text-align:right;margin-left:6px"></span></div>`).join('');
  // per-seat price (avg) for auto-suggesting charge/refund amounts
